package tableselection

import (
	"context"
	"strings"

	"charm.land/bubbles/v2/key"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	appconfig "github.com/wolfwfr/dynamite/pkg"
	"github.com/wolfwfr/dynamite/pkg/ui/internal/messages"
	"github.com/wolfwfr/dynamite/pkg/ui/internal/styles"
	"github.com/wolfwfr/dynamite/pkg/ui/internal/views/util/keymaps"
	u "github.com/wolfwfr/dynamite/pkg/util"
)

type paneID int

const (
	tablePaneID paneID = iota
	detailsPaneID
)

type TableSelection struct {
	// shared config
	config *appconfig.Config

	// view window
	window struct {
		width  int
		height int
	}

	// key map
	KeyMap *TableViewKeyMap

	// Additional Keys
	AddKeyMap keymaps.AdditionalKeys

	// panes
	tablePane   *tableSelectionPane
	detailsPane *detailsPane

	zoomEnabled bool

	focused    paneID
	zoomtarget paneID
}

var (
	borderStyle  = styles.BorderStyle
	focusedStyle = styles.FocusedBorderStyle
)

func (m *TableSelection) renderBorder(paneID paneID, content string) string {
	if m.focused == paneID {
		return focusedStyle.Render(content)
	}
	return borderStyle.Render(content)
}

type Option func(t *TableSelection)

func WithAdditionalKeys(keys keymaps.AdditionalKeys) Option {
	return func(t *TableSelection) {
		t.AddKeyMap = keys
	}
}

func NewTableSelectionView(ctx context.Context, config *appconfig.Config, opts ...Option) *TableSelection {
	t := &TableSelection{
		config: config,
		KeyMap: DefaultTableViewKeyMap(),
	}

	for _, o := range opts {
		o(t)
	}

	t.tablePane = newTableSelectionPane(ctx, config, withTablePaneKeys(t.AddKeyMap))
	t.detailsPane = newDetailsPane(ctx, config, withDetailsPaneKeys(t.AddKeyMap))

	return t
}

func (m *TableSelection) Init() tea.Cmd {
	return tea.Batch(m.tablePane.Init(), m.detailsPane.Init())
}

// update handles the message and if it does not detect a keypress that it can
// map itself proceeds to forward the message to the model's children
func (m *TableSelection) Update(msg tea.Msg) tea.Cmd {
	var cmd tea.Cmd
	switch msg := msg.(type) {
	case tea.KeyPressMsg:
		switch {
		case key.Matches(msg, m.KeyMap.MoveFocus):
			m.moveFocus()
			return nil
		case key.Matches(msg, m.KeyMap.Regions):
			return m.ToggleRegionsDialog()
		}
	case tea.WindowSizeMsg:
		m.window.height = msg.Height
		m.window.width = msg.Width
		m.applySize()
	case messages.ZoomToggleTableSelectionPane, messages.ZoomToggleTableDetailsPane:
		cmd = m.handleZoom(msg)
	}

	return tea.Batch(cmd, m.forward(msg))
}

// forward takes a message and decides to broadcast or to forward only to focused
// children
func (m *TableSelection) forward(msg tea.Msg) tea.Cmd {
	if _, isKeyPress := msg.(tea.KeyPressMsg); isKeyPress {
		return m.routeToFocusedOnly(msg)
	}
	return m.broadcast(msg)
}

// broadcast takes a message and forwards it to all children
func (m TableSelection) broadcast(msg tea.Msg) tea.Cmd {
	cmds := []tea.Cmd{}
	cmds = append(cmds, m.tablePane.Update(msg))
	cmds = append(cmds, m.detailsPane.Update(msg))
	return tea.Batch(cmds...)
}

// routeToFocusedOnly takes a message and only routes it to a single child, the
// active child with highest precedence (dialogs take precedence over views)
func (m *TableSelection) routeToFocusedOnly(msg tea.Msg) tea.Cmd {
	switch m.focused {
	case tablePaneID:
		return m.tablePane.Update(msg)
	case detailsPaneID:
		return m.detailsPane.Update(msg)
	default:
		panic("focused pane not found")
	}
}

func (m *TableSelection) handleZoom(msg tea.Msg) tea.Cmd {
	switch msg.(type) {
	case messages.ZoomToggleTableSelectionPane:
		m.zoomEnabled = !m.zoomEnabled
		m.zoomtarget = tablePaneID
		m.focused = tablePaneID
		m.KeyMap.MoveFocus.SetEnabled(!m.KeyMap.MoveFocus.Enabled())
	case messages.ZoomToggleTableDetailsPane:
		m.zoomEnabled = !m.zoomEnabled
		m.zoomtarget = detailsPaneID
		m.focused = detailsPaneID
		m.KeyMap.MoveFocus.SetEnabled(!m.KeyMap.MoveFocus.Enabled())
	}
	m.applySize()
	return nil
}

func (m TableSelection) ToggleRegionsDialog() tea.Cmd {
	return func() tea.Msg {
		return messages.ToggleRegions{}
	}
}

func (m *TableSelection) applySize() {
	w := u.Ternary(m.window.width, m.window.width/2, m.zoomEnabled)
	borderStyle = borderStyle.
		Height(m.window.height - 2).
		Width(w)

	focusedStyle = focusedStyle.
		Height(m.window.height - 2).
		Width(w)

	m.tablePane.applySize(m.window.height-2-3, w-4)
	m.detailsPane.applySize(m.window.height-2-3, w-4)
}

func (m *TableSelection) moveFocus() {
	m.focused++
	if m.focused > detailsPaneID {
		m.focused = tablePaneID
	}
}

func (m *TableSelection) View() string {
	s := strings.Builder{}
	s.WriteString(lipgloss.JoinHorizontal(lipgloss.Top,
		u.Ternary(m.renderBorder(tablePaneID, m.tablePane.View()), "", !m.zoomEnabled || m.zoomtarget == tablePaneID),
		u.Ternary(m.renderBorder(detailsPaneID, m.detailsPane.View()), "", !m.zoomEnabled || m.zoomtarget == detailsPaneID),
	))
	return s.String()
}

package tableselection

import (
	"context"
	"fmt"
	"image/color"
	"slices"
	"strings"
	"time"

	"charm.land/bubbles/v2/key"
	"charm.land/bubbles/v2/spinner"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/atotto/clipboard"

	appconfig "github.com/ron/ecsx/pkg"
	"github.com/ron/ecsx/pkg/ui/internal/adapters/dynamodb"
	apitypes "github.com/ron/ecsx/pkg/ui/internal/adapters/ecs/types"
	"github.com/ron/ecsx/pkg/ui/internal/components/search"
	"github.com/ron/ecsx/pkg/ui/internal/components/table"
	"github.com/ron/ecsx/pkg/ui/internal/messages"
	commonstyles "github.com/ron/ecsx/pkg/ui/internal/styles"
	"github.com/ron/ecsx/pkg/ui/internal/views/util/keymaps"
	u "github.com/ron/ecsx/pkg/util"

	"github.com/aws/aws-sdk-go-v2/service/ecs"
)

type TableStyles struct {
	SelectedBackground    color.Color
	SearchMatchBackground color.Color
}

type tableSelectionPane struct {
	// top-level context
	ctx context.Context

	client *ecs.Client
	// styles
	styles struct {
		Table TableStyles
	}

	// spinner
	spinner struct {
		active bool
		model  spinner.Model
		text   string
	}
	// cancel last call context (debounce)
	cancelDetails func()
	debounceDur   time.Duration

	// paging tables
	cancelTables func()
	lastPageKey  *string

	// standard timeout
	stdTO time.Duration

	// shared config
	config *appconfig.Config

	// errorText
	err error

	// pane's view window
	window struct {
		width  int
		height int
	}

	// fuzzy finding
	search *search.SearchBox

	// key map
	KeyMap *TablePaneKeyMap

	// Additional Keys
	AddKeyMap keymaps.AdditionalKeys

	// the underlying table
	content *table.Model

	// the table-names retrieved from dynamodb
	tables []string

	// filtering parameters
	tablefiltering struct {
		matchedTables []int   // indices referring to tables
		matchedRunes  [][]int //matches by index to tablefiltering.mathedTables
		enabled       bool
	}

	// index to most recently received table details
	lastTableDetails int // index

	// table details
	details *apitypes.DescribeTableResponse
}

type tablePaneOption func(p *tableSelectionPane)

// withTablePaneKeys
func withTablePaneKeys(keys keymaps.AdditionalKeys) tablePaneOption {
	return func(t *tableSelectionPane) {
		t.AddKeyMap = keys
	}
}

func newTableSelectionPane(ctx context.Context, config *appconfig.Config, opts ...tablePaneOption) *tableSelectionPane {
	p := &tableSelectionPane{
		ctx:           ctx,
		cancelDetails: func() {}, // noop on init
		cancelTables:  func() {}, // noop on init
		debounceDur:   50 * time.Millisecond,
		config:        config,
		stdTO:         30 * time.Second,
		KeyMap:        DefaultTablePaneKeyMap(),
	}

	{ // contents table
		t := table.New(
			table.WithColumns([]table.Column{{Title: "table-name", Width: 64}}),
			table.WithFocused(true),
			table.WithFieldDelegate(p.TableRowFieldDelegate),
		)
		s := table.DefaultStyles()
		s.Header = s.Header.
			BorderStyle(lipgloss.NormalBorder()).
			BorderForeground(commonstyles.TableDefaultFg).
			BorderBottom(true).
			Bold(false)
		s.Selected = s.Selected.
			Foreground(commonstyles.TableSelectedFg).
			Background(commonstyles.TableSelectedBg).
			Bold(false)
		t.SetStyles(s)

		st := TableStyles{
			SelectedBackground:    commonstyles.TableSelectedBg,
			SearchMatchBackground: commonstyles.SearchHighlight,
		}

		p.content = t
		p.styles.Table = st
	}

	{ // spinner
		sp := spinner.New()
		sp.Spinner = spinner.Dot
		sp.Style = lipgloss.NewStyle().
			Foreground(lipgloss.Color("205")).
			PaddingLeft(1)
		p.spinner.model = sp
		p.spinner.text = "obtaining next page..."
	}

	{ // search box
		p.search = search.NewSearchBox(
			search.SearchCallbacks{
				ToSearch: func(string) []string {
					return table.Rows(p.content.Rows()).ToStrings()
				},
				EmptyInput: func() tea.Cmd {
					p.tablefiltering.enabled = false
					p.tablefiltering.matchedTables = make([]int, 0)
					p.tablefiltering.matchedRunes = make([][]int, 0)
					p.content.ResetVirtualRows()
					return p.MaybePreviewItem(true)
				},
				Results: func(_ string, results []search.FilteredItem) tea.Cmd {
					p.tablefiltering.enabled = true
					p.tablefiltering.matchedTables = make([]int, len(results))
					p.tablefiltering.matchedRunes = make([][]int, len(results))
					rows := p.content.Rows()
					filtered := make([]table.Row, len(results))
					for i, match := range results {
						filtered[i] = rows[match.Index]
						p.tablefiltering.matchedTables[i] = match.Index
						p.tablefiltering.matchedRunes[i] = match.Matches
					}
					p.content.SetVirtualRows(filtered)
					return nil
				},
				Reset: func(searchHeight int) tea.Cmd {
					p.tablefiltering.enabled = false
					p.tablefiltering.matchedTables = make([]int, 0)
					p.tablefiltering.matchedRunes = make([][]int, 0)
					p.content.ResetVirtualRows()
					p.updateSize()
					return p.MaybePreviewItem(true)
				},
				SearchBoxOpens: func(searchHeight int) tea.Cmd {
					p.updateSize()
					return nil
				},
			},
		)
	}

	for _, o := range opts {
		o(p)
	}

	if !keymaps.UniqueKeyMaps(p.KeyMap.ShortHelp(), p.AddKeyMap.Bindings()) {
		panic("overlapping keymaps!")
	}

	return p
}

func (m *tableSelectionPane) cleanSlate() {
	m.err = nil
}

func (m *tableSelectionPane) Init() tea.Cmd {
	m.search.Reset()
	m.content.ResetVirtualRows()
	m.content.SetCursor(0)
	m.cleanSlate()
	m.lastPageKey = nil
	m.tables = []string{}

	// cancel any lingering calls
	m.cancelTables()
	m.cancelDetails()
	return m.pageNext(true)
}

func (m *tableSelectionPane) activateSpinner() tea.Cmd {
	m.spinner.active = true
	m.updateSize()
	return m.spinner.model.Tick
}

func (m *tableSelectionPane) deactivateSpinner() {
	m.spinner.active = false
	m.updateSize()
}

func (m *tableSelectionPane) pageNext(init bool) tea.Cmd {
	spinnerCmd := m.activateSpinner()
	if !init && m.lastPageKey == nil { // done paginating
		m.deactivateSpinner()
		return nil
	}
	client := m.config.Client
	region := m.config.Region
	ctx, cc := context.WithTimeout(m.ctx, m.stdTO)
	m.cancelTables = cc
	page := func() tea.Msg {
		defer cc()
		limit := min(100, m.config.MaxTables-len(m.tables)) // 100 is max
		if limit == 0 {
			return nil
		}
		out, err := ecs.ListClusters(client, ctx)

		msg := messages.TablePageReady{
			Err:    err,
			Region: region,
		}
		if out != nil {
			msg.Tables = out.TableNames
			msg.PaginationKey = out.LastEvaluatedTableName
		}
		return msg
	}
	return tea.Batch(page, spinnerCmd)
}

func (m *tableSelectionPane) processPage(msg messages.TablePageReady, preview bool) tea.Cmd {
	if msg.Region != m.config.Region { // expired
		return nil
	}
	if msg.Err != nil {
		m.err = msg.Err
		return nil
	}
	init := len(m.tables) == 0
	newTables := msg.Tables
	m.tables = append(m.tables, newTables...)
	m.lastPageKey = msg.PaginationKey

	// parse and set rows of the new tables
	rows := make([]table.Row, len(newTables))
	for i := range newTables {
		rows[i] = []table.Field{
			enrichedField{value: newTables[i]},
		}
	}
	if init {
		m.content.SetRows(rows)
	} else {
		m.content.AppendRows(rows)
	}

	// return commands
	cmds := []tea.Cmd{}
	if preview {
		cmds = append(cmds, m.MaybePreviewItem(true))
	}
	if len(m.tables) < m.config.MaxTables {
		cmds = append(cmds, m.pageNext(false))
	}
	return tea.Batch(cmds...)
}

func (m *tableSelectionPane) Update(msg tea.Msg) tea.Cmd {
	cmds := []tea.Cmd{}
	switch msg := msg.(type) {
	case messages.TableDetails:
		m.details = msg.Details
		return nil
	case messages.SwitchView:
		if msg.NewView != messages.Table_selection {
			return nil
		}
		return m.MaybePreviewItem(true)
	case messages.TablePageReady:
		return m.processPage(msg, len(m.tables) == 0)
	case spinner.TickMsg:
		if !m.spinner.active {
			return nil
		}
		var cmd tea.Cmd
		m.spinner.model, cmd = m.spinner.model.Update(msg)
		return cmd
	}

	if search.IsSearchBoxMessage(msg) || m.search.IsFocused() {
		cmds = append(cmds, m.search.Update(msg))
	} else {
		cmds = append(cmds, m.handleNavigation(msg))
	}

	cmds = append(cmds, m.MaybePreviewItem(false))
	return tea.Batch(cmds...)
}

// handleNavigation handles events when search is not active.
func (m *tableSelectionPane) handleNavigation(msg tea.Msg) tea.Cmd {
	cmds := []tea.Cmd{}
	switch msg := msg.(type) {
	case tea.KeyPressMsg:
		switch {
		case key.Matches(msg, m.KeyMap.Search):
			cmds = append(cmds, m.search.OpenSearchBox())
		case key.Matches(msg, m.KeyMap.Select):
			return m.selectTable()
		case key.Matches(msg, m.KeyMap.Zoom):
			return m.Zoom()
		case key.Matches(msg, m.KeyMap.Esc):
			m.search.Reset()
		case key.Matches(msg, m.KeyMap.Reload):
			return m.Init()
		case key.Matches(msg, m.KeyMap.Copy):
			return m.copy()
		default:
			if match, call := m.AddKeyMap.Matches(msg); match {
				return call
			}
		}
	}
	cmds = append(cmds, m.content.Update(msg))
	return tea.Batch(cmds...)
}

type enrichedField struct {
	value string
}

// Value implements the matching table.Field interface function
func (f enrichedField) Value() string {
	return f.value
}

func (m *tableSelectionPane) TableRowFieldDelegate(row table.Row, col table.Column, colIdx, rowIdx, colW, padL, padR int, selected bool) string {
	fullWidth := colW + padL + padR

	// obtain field in question
	field := row[colIdx].(enrichedField)

	enforceWidth := lipgloss.NewStyle().Width(fullWidth).MaxWidth(fullWidth).Inline(true).Render
	padding := lipgloss.NewStyle().Padding(0, 1).Render

	// no special styling if not selected or no filtering is applied
	if !selected && (!m.tablefiltering.enabled) {
		return padding(enforceWidth(field.value))
	}

	// empty style to start with
	style := commonstyles.LineStyle{}.AppendStringLG(field.value, lipgloss.NewStyle())

	// add padding
	style = style.SetRightPaddingLast(padR)
	style = style.SetLeftPaddingFirst(padL)

	// apply background styling for selected row
	if selected {
		// fill up any remaining space
		if len([]rune(field.value)) < fullWidth {
			st, _ := style.GetAt(len([]rune(field.value)) - 1)
			style = style.Override(len([]rune(field.value))-1, st.PaddingRight(fullWidth-len([]rune(field.value))))
		}
		style = style.SetBackgroundAll(m.styles.Table.SelectedBackground)
	}

	// override background styling for search matches
	if m.tablefiltering.enabled {
		for _, idx := range m.tablefiltering.matchedRunes[rowIdx] {
			runeStyle, _ := style.GetAt(idx)
			c := m.styles.Table.SearchMatchBackground
			if selected {
				c = lipgloss.Blend1D(10, c, m.styles.Table.SelectedBackground)[3]
			}
			style = style.Override(idx, runeStyle.Background(c))
		}
	}

	return enforceWidth(style.Render(field.value))
}

func (m *tableSelectionPane) copy() tea.Cmd {
	r := m.content.VisualRows()
	c := max(0, m.content.Cursor())
	if c >= len(r) {
		return nil
	}

	if err := clipboard.WriteAll(r[c].String()); err != nil {
		return func() tea.Msg {
			return messages.ToggleNotificationDialog{Error: fmt.Errorf("failed to copy: %w", err)}
		}
	}
	return notifyCopySuccess
}

// force is used on new pane initialization because lastPreviewItem could be 0
func (m *tableSelectionPane) MaybePreviewItem(force bool) tea.Cmd {
	if len(m.tables) == 0 || (m.tablefiltering.enabled && len(m.tablefiltering.matchedTables) == 0) {
		return func() tea.Msg {
			return messages.TableDetails{
				Details: nil,
			}
		}
	}

	idx := m.content.Cursor()
	if len(m.tablefiltering.matchedTables) > 0 { // cursor refers to filtered items
		idx = m.tablefiltering.matchedTables[idx]
	}
	if idx == m.lastTableDetails && !force {
		return nil
	}
	m.lastTableDetails = idx
	table := m.tables[idx]

	// prepare debounce cancellation
	m.cancelDetails()
	ctx, cc := context.WithCancel(m.ctx)
	m.cancelDetails = cc

	return func() tea.Msg {
		time.Sleep(m.debounceDur)
		if ctx.Err() != nil { // context canceled
			return nil // debounce
		}

		ctx, cc := context.WithTimeout(ctx, m.stdTO)
		defer cc()
		details, err := dynamodb.DescribeTable(m.config.Client, ctx, table)
		if err != nil {
			return nil
		}

		return messages.TableDetails{
			Details: details,
		}
	}
}

func (m *tableSelectionPane) Zoom() tea.Cmd {
	return func() tea.Msg {
		return messages.ZoomToggleTableSelectionPane{}
	}
}

func (m *tableSelectionPane) selectTable() tea.Cmd {
	m.cancelDetails()
	m.cancelTables()
	switchView := func() tea.Msg {
		return messages.SwitchView{
			OldView: messages.Table_selection,
			NewView: messages.Item_selection,
		}
	}
	rowP := m.content.SelectedRow()
	if rowP == nil {
		return nil
	}
	row := *rowP
	if len(row) == 0 {
		return nil // nothing to select
	}
	if m.details == nil || (m.details.TableName != nil && *m.details.TableName != row[0].Value()) {
		m.cleanSlate()
		ctx, cc := context.WithTimeout(m.ctx, m.stdTO)
		defer cc()
		details, err := dynamodb.DescribeTable(m.config.Client, ctx, row[0].Value())
		if err != nil {
			m.err = err
			return nil
		}
		m.details = details
	}
	details := m.details

	selectTable := func() tea.Msg {
		return messages.SelectTable{
			TableName:    row[0].Value(),
			TableDetails: *details,
		}
	}
	return tea.Batch(switchView, selectTable)
}

func (m *tableSelectionPane) applySize(height, width int) {
	m.window.height = height
	m.window.width = width
	m.updateSize()
}

// updateSize updates dimensions of the pane's contents based on the current
// window dimensions.
func (m *tableSelectionPane) updateSize() {
	h, w := m.window.height, m.window.width

	searchBoxH := u.Ternary(m.search.GetHeight(), 0, m.search.IsEnabled())
	m.content.SetHeight(h - searchBoxH - u.Ternary(1, 0, m.spinner.active))
	m.content.SetWidth(w)
	m.search.SetWidth(w)
}

func (m *tableSelectionPane) View() string {
	if m.err != nil {
		return m.err.Error()
	}
	content := u.Ternary(m.content.View(), m.noContentMessage(), len(m.content.Rows()) > 0)
	rendering := []string{content, m.search.View()}
	if m.spinner.active {
		rendering = slices.Insert(rendering, 1, fmt.Sprintf("%s %s", m.spinner.model.View(), m.spinner.text))
	}
	return lipgloss.JoinVertical(lipgloss.Left, rendering...)
}

func (m *tableSelectionPane) noContentMessage() string {
	if m.spinner.active {
		return ""
	}
	s := strings.Builder{}
	fmt.Fprintf(&s, "==================================================\n")
	fmt.Fprintf(&s, "             NO TABLES IN THIS REGION             \n")
	fmt.Fprintf(&s, "==================================================\n")
	return s.String()
}

func notifyCopySuccess() tea.Msg {
	return messages.ToggleNotificationDialog{Msg: "Copied!", Duration: 1 * time.Second}
}

package tableselection

import (
	"context"
	"fmt"
	"strings"
	"time"

	"charm.land/bubbles/v2/key"
	"charm.land/bubbles/v2/viewport"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	dynamodbtypes "github.com/aws/aws-sdk-go-v2/service/dynamodb/types"

	appconfig "github.com/wolfwfr/dynamite/pkg"
	apitypes "github.com/wolfwfr/dynamite/pkg/ui/internal/adapters/dynamodb/types"
	"github.com/wolfwfr/dynamite/pkg/ui/internal/messages"
	"github.com/wolfwfr/dynamite/pkg/ui/internal/styles"
	"github.com/wolfwfr/dynamite/pkg/ui/internal/views/util/keymaps"
	u "github.com/wolfwfr/dynamite/pkg/util"
)

type detailsPane struct {
	// shared config
	config *appconfig.Config

	// errorText
	err error

	// pane's view window
	window struct {
		width  int
		height int
	}

	// key map
	KeyMap *DetailsPaneKeyMap

	// Additional Keys
	AddKeyMap keymaps.AdditionalKeys

	styles detailsStyles

	content viewport.Model
}

type detailsStyles struct {
	headerStyle    lipgloss.Style
	fieldNameStyle lipgloss.Style
}

type detailsPaneOption func(p *detailsPane)

func withDetailsPaneKeys(keys keymaps.AdditionalKeys) detailsPaneOption {
	return func(t *detailsPane) {
		t.AddKeyMap = keys
	}
}

func newDetailsPane(ctx context.Context, config *appconfig.Config, opts ...detailsPaneOption) *detailsPane {
	step := 5
	c := viewport.New(viewport.WithHeight(20)) // content
	c.SoftWrap = false
	c.SetHorizontalStep(step)
	c.KeyMap.Left.SetHelp("←/h", "left")
	c.KeyMap.Right.SetHelp("→/l", "right")
	p := &detailsPane{
		config:  config,
		content: c,
		KeyMap:  DefaultDetailsKeyMap(),
	}

	p.styles = detailsStyles{
		headerStyle:    lipgloss.NewStyle().Bold(true).Foreground(styles.ViewFocusBorderColour).PaddingBottom(1),
		fieldNameStyle: lipgloss.NewStyle().Foreground(styles.SubtleColour), //.Bold(true),
	}

	for _, o := range opts {
		o(p)
	}

	if !keymaps.UniqueKeyMaps(p.KeyMap.ShortHelp(), p.AddKeyMap.Bindings()) {
		panic("overlapping keymaps!")
	}
	return p
}

func (m *detailsPane) cleanSlate() {
	m.err = nil
}

func (m *detailsPane) Init() tea.Cmd {
	m.cleanSlate()
	return nil
}

func (m *detailsPane) Update(msg tea.Msg) (cmd tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyPressMsg:
		switch {
		case key.Matches(msg, m.KeyMap.Zoom):
			return m.Zoom()
		default:
			if match, call := m.AddKeyMap.Matches(msg); match {
				return call
			}
		}
	case messages.TableDetails:
		m.content.SetContent(renderDetails(msg.Details, m.styles))
		return nil
	}

	m.content, cmd = m.content.Update(msg)
	return
}

func renderDetails(details *apitypes.DescribeTableResponse, styles detailsStyles) string {
	if details == nil {
		return ""
	}
	totalSize := *details.TableSizeBytes
	globalIdxSize := int64(0)
	globalIdxItemCount := int64(0)
	localIdxSize := int64(0)
	localIdxItemCount := int64(0)
	for _, i := range details.GlobalSecondaryIndexes {
		totalSize += *i.IndexSizeBytes
		globalIdxSize += *i.IndexSizeBytes
		globalIdxItemCount += *i.ItemCount
	}
	for _, i := range details.LocalSecondaryIndexes {
		totalSize += *i.IndexSizeBytes
		localIdxSize += *i.IndexSizeBytes
		localIdxItemCount += *i.ItemCount
	}

	name := u.IfNotNil(details.TableName, "")
	arn := u.IfNotNil(details.TableArn, "")
	id := u.IfNotNil(details.TableId, "")

	header := styles.headerStyle.Render
	field := styles.fieldNameStyle.Render

	s := strings.Builder{}
	fmt.Fprintf(&s, "%s\n", header("GENERAL"))
	fmt.Fprintf(&s, "%s:   %s\n", field("Table name"), name)
	fmt.Fprintf(&s, "%s:    %s\n", field("Table ARN"), arn)
	fmt.Fprintf(&s, "%s:     %s\n", field("Table ID"), id)
	fmt.Fprintf(&s, "\n")
	if details.TableClassSummary != nil {
		fmt.Fprintf(&s, "%s:  %s\n", field("Table Class"), details.TableClassSummary.TableClass)
		fmt.Fprintf(&s, "\n")
	}
	fmt.Fprintf(&s, "%s:   %s\n", field("Created At"), details.CreationDateTime.Format(time.RFC1123Z))
	fmt.Fprintf(&s, "\n")
	fmt.Fprintf(&s, "%s\n", header("COUNT"))
	fmt.Fprintf(&s, "%s:                   %d\n", field("Table Item Count"), *details.ItemCount)
	fmt.Fprintf(&s, "%s:  %d\n", field("Global Secondary Index Item Count"), globalIdxItemCount)
	fmt.Fprintf(&s, "%s:   %d\n", field("Local Secondary Index Item Count"), localIdxItemCount)
	fmt.Fprintf(&s, "\n")
	fmt.Fprintf(&s, "%s\n", header("SIZE"))
	fmt.Fprintf(&s, "%s:                   %s\n", field("Total Size"), formatBytes(totalSize))
	fmt.Fprintf(&s, "%s:                   %s\n", field("Table Size"), formatBytes(*details.TableSizeBytes))
	fmt.Fprintf(&s, "%s:  %s\n", field("Global Secondary Index Size"), formatBytes(globalIdxSize))
	fmt.Fprintf(&s, "%s:   %s\n", field("Local Secondary Index Size"), formatBytes(localIdxSize))
	fmt.Fprintf(&s, "\n")
	fmt.Fprintf(&s, "%s\n", header("TABLE KEYS"))
	hash, rang := primaryKeysFromSchema(details.KeySchema)
	fmt.Fprintf(&s, "%s", formatKeys(hash, rang, "", details.AttributeDefinitions, styles))
	fmt.Fprintf(&s, "\n")
	if len(details.GlobalSecondaryIndexes) > 0 {
		fmt.Fprintf(&s, "%s\n", header("GLOBAL SECONDARY INDICES"))
		for i, idx := range details.GlobalSecondaryIndexes {
			fmt.Fprintf(&s, "%s: %s\n", field("Index Name"), *idx.IndexName)
			fmt.Fprintf(&s, "%s:  %s\n", field("Index ARN"), *idx.IndexArn)
			fmt.Fprintf(&s, "\n")
			hash, rang := primaryKeysFromSchema(idx.KeySchema)
			fmt.Fprintf(&s, "%s", formatKeys(hash, rang, "  ", details.AttributeDefinitions, styles))
			if i != len(details.GlobalSecondaryIndexes)-1 {
				fmt.Fprintf(&s, "\n")
			}
		}
		fmt.Fprintf(&s, "\n")
	}
	if len(details.LocalSecondaryIndexes) > 0 {
		fmt.Fprintf(&s, "%s\n", header("LOCAL SECONDARY INDICES"))
		for i, idx := range details.LocalSecondaryIndexes {
			fmt.Fprintf(&s, "%s: %s\n", field("Index Name"), *idx.IndexName)
			fmt.Fprintf(&s, "%s:  %s\n", field("Index ARN"), *idx.IndexArn)
			fmt.Fprintf(&s, "\n")
			hash, rang := primaryKeysFromSchema(idx.KeySchema)
			fmt.Fprintf(&s, "%s", formatKeys(hash, rang, "  ", details.AttributeDefinitions, styles))
			if i != len(details.LocalSecondaryIndexes)-1 {
				fmt.Fprintf(&s, "\n")
			}
		}
		fmt.Fprintf(&s, "\n")
	}
	fmt.Fprintf(&s, "%s\n", header("SECURITY"))
	fmt.Fprintf(&s, "%s: %t\n", field("Deletion Protection Enabled"), *details.DeletionProtectionEnabled)
	fmt.Fprintf(&s, "\n")
	if details.BillingModeSummary != nil {
		fmt.Fprintf(&s, "%s\n", header("BILLING"))
		fmt.Fprintf(&s, "%s: %s\n", field("Billing Mode"), details.BillingModeSummary.BillingMode)
		fmt.Fprintf(&s, "\n")
	}
	if details.ProvisionedThroughput != nil {
		fmt.Fprintf(&s, "%s\n", header("THROUGHPUT PROVISIONED"))
		fmt.Fprintf(&s, "%s:   %d\n", field("Read Capacity Units"), *details.ProvisionedThroughput.ReadCapacityUnits)
		fmt.Fprintf(&s, "%s:  %d\n", field("Write Capacity Units"), *details.ProvisionedThroughput.WriteCapacityUnits)
		fmt.Fprintf(&s, "\n")
	}
	if details.OnDemandThroughput != nil {
		fmt.Fprintf(&s, "%s\n", header("THROUGHPUT ON DEMAND"))
		fmt.Fprintf(&s, "%s:   %d\n", field("Max Read Capacity Units"), *details.OnDemandThroughput.MaxReadRequestUnits)
		fmt.Fprintf(&s, "%s:  %d\n", field("Max Write Capacity Units"), *details.OnDemandThroughput.MaxWriteRequestUnits)
		fmt.Fprintf(&s, "\n")
	}
	return s.String()
}

func formatKeys(hash string, rang *string, indentation string, attrDef []dynamodbtypes.AttributeDefinition, styles detailsStyles) string {
	field := styles.fieldNameStyle.Render
	var hashAttr string
	var rangAttr *string
	for _, d := range attrDef {
		if hash == *d.AttributeName {
			hashAttr = string(d.AttributeType)
			if rangAttr != nil || rang == nil {
				break
			}
		}
		if rang != nil && *rang == *d.AttributeName {
			rangAttr = u.ToPtr(string(d.AttributeType))
			if hashAttr != "" {
				break
			}
		}
	}
	hashfmt := fmt.Sprintf("%s%s:  %s\n", indentation, field(fmt.Sprintf("Hash Key  (%s)", hashAttr)), hash)
	if rang == nil {
		return hashfmt
	}
	return fmt.Sprintf("%s%s%s:  %s\n", hashfmt, indentation, field(fmt.Sprintf("Range Key (%s)", *rangAttr)), *rang)
}

func formatBytes(bytes int64) string {
	bytesF := float64(bytes)
	sizes := []string{"B", "kB", "MB", "GB", "TB", "PB", "EB"}
	var i int
	for i < len(sizes)-1 {
		if bytesF < 1000 {
			break
		}
		i++
		bytesF = bytesF / 1000
	}
	return fmt.Sprintf("%.2f %s", bytesF, sizes[i])
}

func (m *detailsPane) Zoom() tea.Cmd {
	return func() tea.Msg {
		return messages.ZoomToggleTableDetailsPane{}
	}
}

func (m *detailsPane) applySize(height, width int) {
	// m.content.applySize(m.window.height-2-3, m.window.width/2-4)
	m.window.height = height
	m.window.width = width
	m.content.SetHeight(height)
	m.content.SetWidth(width)
}

func (m *detailsPane) View() string {
	if m.err != nil {
		return m.err.Error()
	}
	return m.content.View()
}

func primaryKeysFromSchema(s []dynamodbtypes.KeySchemaElement) (hash string, rang *string) {
	for _, e := range s {
		if e.KeyType == dynamodbtypes.KeyTypeHash {
			hash = *e.AttributeName
		} else {
			rang = e.AttributeName
		}
	}
	return
}

