// ClusterFromConnector converts a connector cluster type to an adapter cluster type.
func ClusterFromConnector(c ecstypes.Cluster) ClusterItem {
	return ClusterItem{
		Name:               c.Name,
		ARN:                c.ARN,
		Status:             c.Status,
		ContainerInstances: c.ContainerInstances,
