)

// ListTasks calls the ECS connector and transforms the result for UI display.
func ListTasks(client *ecs.Client, ctx context.Context, cluster, service string) ([]apitypes.TaskItem, error) {
	tasks, err := connector.ListTasks(client, ctx, cluster, service)
	if err != nil {
		return nil, err
	}
	items := make([]apitypes.TaskItem, len(tasks))
	for i, t := range tasks {
		items[i] = apitypes.TaskFromConnector(t)
	}
	return items, nil
}

	case tasks.BackToServicesMsg:
		m.activeView = messages.ServiceSelection
		return m, m.services.Load(msg.Cluster)
	}

	return m, m.forward(msg)
}

func (m Model) forward(msg tea.Msg) tea.Cmd {
	switch msg.(type) {
	case tea.WindowSizeMsg:
		return m.broadcast(msg)
	default:
		return m.routeToActiveOnly(msg)
	}
}

func (m Model) routeToActiveOnly(msg tea.Msg) tea.Cmd {
	switch m.activeView {
	case messages.ClusterSelection:
		return m.clusters.Update(msg)
	case messages.ServiceSelection:
		return m.services.Update(msg)
	case messages.TaskSelection:
		return m.tasks.Update(msg)
	}
	return nil
}

func (m Model) broadcast(msg tea.Msg) tea.Cmd {
	return tea.Batch(
		m.clusters.Update(msg),
		m.services.Update(msg),
		m.tasks.Update(msg),
	)
}

func (m Model) View() tea.View {
	var page string
	switch m.activeView {
	case messages.ClusterSelection:
		page = m.clusters.View()
	case messages.ServiceSelection:
		page = m.services.View()
	case messages.TaskSelection:
		page = m.tasks.View()
	}
	v := tea.NewView(page)
	v.AltScreen = true
	return v
}

